import React from "react";
import Navbar from "../components/Navbar";
import bgVideo from "../assets/.mp4";

function Home() {
  return (
    <div>
      <Navbar />

      <div style={{ textAlign: "center", marginTop: "50px" }}>
        <h1>Welcome to College Event Management System</h1>
        <p>
          Register for exciting college events, generate your QR code,
          and participate easily.
        </p>

        <h3>Features</h3>
        <ul style={{ listStyle: "none" }}>
          <li>🎫 Event Registration</li>
          <li>📱 QR Code for Entry</li>
          <li>💳 Online Payment</li>
          <li>📊 Admin QR Scanner</li>
        </ul>
      </div>
    </div>
  );
}

export default Home;
